DROP POLICY apk_forms_select_auth ON public.apk_forms;
DROP POLICY apk_tenant_select ON public.apk_forms;
CREATE POLICY apk_forms_select_tenant ON public.apk_forms
  FOR SELECT TO authenticated
  USING (tenant_id = (SELECT public.get_my_tenant_id()));

DROP POLICY apk_audit_select_auth ON public.apk_audit;
CREATE POLICY apk_audit_select_tenant ON public.apk_audit
  FOR SELECT TO authenticated
  USING (form_id IN (SELECT id FROM public.apk_forms
                     WHERE tenant_id = (SELECT public.get_my_tenant_id())));

DROP POLICY apk_forms_update_anon ON public.apk_forms;
DROP POLICY apk_tenant_update ON public.apk_forms;
CREATE POLICY apk_forms_update_tenant ON public.apk_forms
  FOR UPDATE TO authenticated
  USING (tenant_id = (SELECT public.get_my_tenant_id()))
  WITH CHECK (tenant_id = (SELECT public.get_my_tenant_id()));

DROP POLICY apk_forms_insert_anon ON public.apk_forms;
DROP POLICY apk_tenant_insert ON public.apk_forms;
CREATE POLICY apk_forms_insert_tenant ON public.apk_forms
  FOR INSERT TO authenticated
  WITH CHECK (tenant_id = (SELECT public.get_my_tenant_id()));

DROP POLICY apk_tokens_insert_auth ON public.apk_tokens;
DROP POLICY apk_tokens_insert ON public.apk_tokens;
CREATE POLICY apk_tokens_insert_tenant ON public.apk_tokens
  FOR INSERT TO authenticated
  WITH CHECK (
    tenant_id = (SELECT public.get_my_tenant_id())
    AND (form_id IS NULL OR EXISTS (
      SELECT 1 FROM public.apk_forms f
      WHERE f.id = form_id AND f.tenant_id = (SELECT public.get_my_tenant_id())))
  );

DROP POLICY apk_audit_insert_auth ON public.apk_audit;
CREATE POLICY apk_audit_insert_tenant ON public.apk_audit
  FOR INSERT TO authenticated
  WITH CHECK (form_id IN (SELECT id FROM public.apk_forms
                          WHERE tenant_id = (SELECT public.get_my_tenant_id())));

