CREATE POLICY crm_storage_tenant_folder ON storage.objects
  FOR ALL TO authenticated
  USING (bucket_id IN ('apk-pdfs', 'settlement-files')
         AND (storage.foldername(name))[1] = (SELECT public.get_my_tenant_id())::text)
  WITH CHECK (bucket_id IN ('apk-pdfs', 'settlement-files')
              AND (storage.foldername(name))[1] = (SELECT public.get_my_tenant_id())::text);

