CREATE OR REPLACE FUNCTION public.crm_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM crm_profiles WHERE id = auth.uid()
    AND rola IN ('ADMIN GOD','ADMIN BROKER','BOARD','ADMINISTRACJA'))
$$;

DROP POLICY tenant_isolation ON public.crm_tenants;
CREATE POLICY crm_tenants_select ON public.crm_tenants FOR SELECT TO authenticated
  USING (id = (SELECT public.get_my_tenant_id()));
CREATE POLICY crm_tenants_update_admin ON public.crm_tenants FOR UPDATE TO authenticated
  USING (id = (SELECT public.get_my_tenant_id()) AND (SELECT public.crm_is_admin()))
  WITH CHECK (id = (SELECT public.get_my_tenant_id()));

DROP POLICY tenant_isolation ON public.crm_profiles;
CREATE POLICY crm_profiles_select ON public.crm_profiles FOR SELECT TO authenticated
  USING (tenant_id = (SELECT public.get_my_tenant_id()));
CREATE POLICY crm_profiles_update ON public.crm_profiles FOR UPDATE TO authenticated
  USING (tenant_id = (SELECT public.get_my_tenant_id())
         AND (id = (SELECT auth.uid()) OR (SELECT public.crm_is_admin())))
  WITH CHECK (tenant_id = (SELECT public.get_my_tenant_id()));
CREATE POLICY crm_profiles_delete_admin ON public.crm_profiles FOR DELETE TO authenticated
  USING (tenant_id = (SELECT public.get_my_tenant_id())
         AND (SELECT public.crm_is_admin()) AND id <> (SELECT auth.uid()));

